76	    /**
77	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
78	     * domain containing at least one dot, with no whitespace in any part.
79	     */
80	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
