82	    /**
83	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email domain
84	     * (the part after the {@code @}, compared case-insensitively) is listed here is rejected: such
85	     * addresses are not durable contact details. Entries are stored lower-cased.
86	     */
87	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
88	        "mailinator.com",
89	        "tempmail.com",
90	        "guerrillamail.com");
