92	    /**
93	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
94	     * new owner's id, customer code, registration date, membership level and membership number.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
