139	    /**
140	     * Fixed region-to-postcode-range lookup used both to validate an owner's optional postcode against
141	     * the region derived from the owner's city ({@link #regionForCity}) and to derive the postcode's own
142	     * region for the {@code customerCode} ({@link #regionForPostcode}). Each value is the inclusive
143	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
144	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
145	     */
146	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
147	        "NSW", new int[] {2000, 2099},
148	        "VIC", new int[] {3000, 3099},
149	        "QLD", new int[] {4000, 4099});
