206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
209	        validateRequiredFields(ownerFieldsDto);
210	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
211	        LocalDate registrationDate = toBusinessDay(
212	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
213	        rejectDailyLimitReached(registrationDate);
214	        HttpHeaders headers = new HttpHeaders();
215	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
216	        String address = normalizeAddress(ownerFieldsDto.getAddress());
217	        owner.setAddress(address);
218	        rejectCityAtCapacity(owner.getCity());
219	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
220	        owner.setTelephone(telephone);
221	        String email = normalizeEmail(ownerFieldsDto.getEmail());
222	        owner.setEmail(email);
223	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
224	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
225	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
226	        rejectDuplicateIdentity(owner);
227	        if (!sharesHousehold) {
228	            rejectHouseholdDuplicate(owner);
229	        }
230	        applyPossibleDuplicate(owner, sharesHousehold);
231	        owner.setRegistrationDate(registrationDate);
232	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
233	        owner.setCustomerCode(generateCustomerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
234	        this.clinicService.saveOwner(owner);
235	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
236	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
237	            owner.getMembershipLevel(), owner.getMembershipNumber());
238	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
239	        applyBulkSignupWarning(ownerDto);
240	        headers.setLocation(UriComponentsBuilder.newInstance()
241	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
242	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
243	    }
