339	    /**
340	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
341	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
342	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
343	     *
344	     * @param ownerFieldsDto the submitted owner fields
345	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
346	     *                                     name of every offending field
347	     */
348	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
349	        List<String> missingFields = new ArrayList<>();
350	        if (isBlank(ownerFieldsDto.getFirstName())) {
351	            missingFields.add("firstName");
352	        }
353	        if (isBlank(ownerFieldsDto.getLastName())) {
354	            missingFields.add("lastName");
355	        }
356	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
357	            missingFields.add("address");
358	        }
359	        if (isBlank(ownerFieldsDto.getCity())) {
360	            missingFields.add("city");
361	        }
362	        if (isBlank(ownerFieldsDto.getTelephone())) {
363	            missingFields.add("telephone");
364	        }
365	        if (!missingFields.isEmpty()) {
366	            throw new InvalidOwnerFieldsException(missingFields);
367	        }
368	    }
369	
370	    private boolean isBlank(String value) {
371	        return value == null || value.isBlank();
372	    }
