374	    /**
375	     * Rejects a supplied {@code registrationDate} that is later than the current server date. A
376	     * {@code null} value means the field was omitted and the registration date will default to the
377	     * server date, so there is nothing to reject. A supplied date on or before today is accepted; the
378	     * raw supplied value is compared against the server date before any business-day adjustment.
379	     *
380	     * @param registrationDate the registration date supplied by the client, or {@code null} if omitted
381	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server date, yielding a
382	     *                                     400 Bad Request response
383	     */
384	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
385	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
386	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
387	        }
388	    }
