390	    /**
391	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
392	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
393	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
394	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
395	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
396	     * The returned value is stored and returned unchanged.
397	     *
398	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
399	     * @param region   the owner's region derived from its city
400	     * @return the postcode to store, or {@code null} if none was supplied
401	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
402	     *                                     out of range for the city's region, yielding a 400 response
403	     */
404	    private String validatePostcode(String postcode, String region) {
405	        if (postcode == null) {
406	            return null;
407	        }
408	        if (!postcode.matches("[0-9]{4}")) {
409	            throw new InvalidOwnerFieldsException(List.of("postcode"));
410	        }
411	        int[] range = REGION_POSTCODES.get(region);
412	        if (range != null) {
413	            int value = Integer.parseInt(postcode);
414	            if (value < range[0] || value > range[1]) {
415	                throw new InvalidOwnerFieldsException(List.of("postcode"));
416	            }
417	        }
418	        return postcode;
419	    }
