421	    /**
422	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
423	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
424	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
425	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
426	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
427	     *
428	     * @param telephone the raw telephone value submitted by the client
429	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
430	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
431	     *                                     400 response
432	     */
433	    private String normalizeTelephone(String telephone) {
434	        String e164 = toE164(telephone);
435	        if (e164 == null) {
436	            throw new InvalidOwnerFieldsException(List.of("telephone"));
437	        }
438	        return e164;
439	    }
440	
441	    /**
442	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
443	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
444	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
445	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
446	     * and when the supplied country code is one with a known national-number length
447	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
448	     * number must have exactly that many digits.
449	     *
450	     * @param telephone the raw telephone value, possibly {@code null}
451	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
452	     */
453	    private String toE164(String telephone) {
454	        if (telephone == null) {
455	            return null;
456	        }
457	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
458	        boolean hasPlus = cleaned.startsWith("+");
459	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
460	        String nationalSignificant = hasPlus
461	            ? digits
462	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
463	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
464	            return null;
465	        }
466	        if (!hasValidNationalNumberLength(nationalSignificant)) {
467	            return null;
468	        }
469	        return "+" + nationalSignificant;
470	    }
471	
472	    /**
473	     * Checks the national-number length of an E.164 number (country code plus national significant
474	     * digits, no leading {@code '+'}) against the per-country requirement in
475	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
476	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
477	     * country code is not listed carries no per-country length requirement and is accepted.
478	     *
479	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
480	     *                            leading {@code '+'}
481	     * @return {@code true} if the national-number length is correct for the country code, or the
482	     *         country code has no listed requirement; {@code false} otherwise
483	     */
484	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
485	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
486	            .filter(nationalSignificant::startsWith)
487	            .max(Comparator.comparingInt(String::length))
488	            .orElse(null);
489	        if (countryCode == null) {
490	            return true;
491	        }
492	        int nationalLength = nationalSignificant.length() - countryCode.length();
493	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
494	    }
495	
496	    /**
497	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
498	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
499	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
500	     * returned value is that address lower-cased.
501	     *
502	     * @param email the raw email value submitted by the client, or {@code null} if omitted
503	     * @return the lower-cased email, or {@code null} if none was supplied
504	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
505	     *                                     or its domain is a disposable-mail domain, yielding a 400
506	     *                                     response
507	     */
508	    private String normalizeEmail(String email) {
509	        if (email == null) {
510	            return null;
511	        }
512	        if (!EMAIL_PATTERN.matcher(email).matches()) {
513	            throw new InvalidOwnerFieldsException(List.of("email"));
514	        }
515	        String normalized = email.toLowerCase(Locale.ROOT);
516	        String domain = normalized.substring(normalized.indexOf('@') + 1);
517	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
518	            throw new InvalidOwnerFieldsException(List.of("email"));
519	        }
520	        return normalized;
521	    }
