523	    /**
524	     * Counts the existing owners that, before this create, already share the given first name and
525	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
526	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
527	     * been saved yet, so it is never included in the count.
528	     *
529	     * @param firstName the first name of the owner being created
530	     * @param lastName  the last name of the owner being created
531	     * @return the number of existing owners sharing both names
532	     */
533	    private int countNamesakes(String firstName, String lastName) {
534	        String normalizedFirstName = normalizeForComparison(firstName);
535	        String normalizedLastName = normalizeForComparison(lastName);
536	        return (int) this.clinicService.findAllOwners().stream()
537	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
538	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
539	            .count();
540	    }
541	
542	    /**
543	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
544	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
545	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
546	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
547	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
548	     * same postcode region, telephone and last name always yield the same customer code.
549	     *
550	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
551	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
552	     * it unique, so distinct owners always receive distinct customer codes.
553	     *
554	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
555	     * @param telephone the owner's normalized (E.164) telephone
556	     * @param lastName  the owner's last name
557	     * @return the formatted, de-duplicated customer code
558	     */
559	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
560	        String region = regionForPostcode(postcode);
561	        String hash8 = hashHex(telephone + lastName, 8);
562	        String baseCode = region + "-" + hash8;
563	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
564	            .map(Owner::getCustomerCode)
565	            .filter(Objects::nonNull)
566	            .collect(Collectors.toSet());
567	        if (!existingCodes.contains(baseCode)) {
568	            return baseCode;
569	        }
570	        int n = 2;
571	        while (existingCodes.contains(baseCode + "-" + n)) {
572	            n++;
573	        }
574	        return baseCode + "-" + n;
575	    }
576	
577	    /**
578	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
579	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
580	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
581	     * {@code <REGION>} segment baked into the {@code customerCode}.
582	     *
583	     * @param postcode the owner's postcode, or {@code null}
584	     * @return the region code, or {@code 'UNKNOWN'}
585	     */
586	    private String regionForPostcode(String postcode) {
587	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
588	            return "UNKNOWN";
589	        }
590	        int value = Integer.parseInt(postcode);
591	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
592	            int[] range = entry.getValue();
593	            if (value >= range[0] && value <= range[1]) {
594	                return entry.getKey();
595	            }
596	        }
597	        return "UNKNOWN";
598	    }
599	
600	    /**
601	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
602	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
603	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
604	     * region.
605	     *
606	     * @param city the owner's city
607	     * @return the region code, or {@code 'UNKNOWN'}
608	     */
609	    private String regionForCity(String city) {
610	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
611	    }
612	
613	    /**
614	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
615	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
616	     * deterministic {@code householdId} (length 12).
617	     *
618	     * @param input  the value to hash
619	     * @param length the number of leading hex characters to return
620	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
621	     */
622	    private String hashHex(String input, int length) {
623	        try {
624	            byte[] digest = MessageDigest.getInstance("SHA-256")
625	                .digest(input.getBytes(StandardCharsets.UTF_8));
626	            StringBuilder hex = new StringBuilder(digest.length * 2);
627	            for (byte b : digest) {
628	                hex.append(String.format("%02x", b));
629	            }
630	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
631	        } catch (NoSuchAlgorithmException e) {
632	            throw new IllegalStateException("SHA-256 algorithm not available", e);
633	        }
634	    }
635	
636	    /**
637	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
638	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
639	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
640	     * has not been saved yet, so it is never included in the count.
641	     *
642	     * @param city the city of the owner being created
643	     * @return the number of existing owners in that city
644	     */
645	    private int countOwnersInCity(String city) {
646	        String normalizedCity = normalizeForComparison(city);
647	        return (int) this.clinicService.findAllOwners().stream()
648	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
649	            .count();
650	    }
651	
652	    /**
653	     * Rejects creation of an owner whose city already contains the maximum number of owners
654	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
655	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
656	     *
657	     * @param city the city of the owner being created
658	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
659	     *                                      owners, yielding a 409 Conflict response
660	     */
661	    private void rejectCityAtCapacity(String city) {
662	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
663	            throw new OwnerCityAtCapacityException(city);
664	        }
665	    }
666	
667	    /**
668	     * Rejects creation of an owner once the given business day has already reached its daily quota
669	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
670	     * being that day — the adjusted business day the owner being created will carry — so the quota
671	     * applies per business day. The owner being created has not been saved yet, so it is never
672	     * included in the count.
673	     *
674	     * @param registrationDate the adjusted business-day registration date of the owner being created
675	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
676	     *                                         carry that registration date, yielding a
677	     *                                         429 Too Many Requests response
678	     */
679	    private void rejectDailyLimitReached(LocalDate registrationDate) {
680	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
681	            throw new DailyOwnerLimitReachedException(registrationDate);
682	        }
683	    }
684	
685	    /**
686	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
687	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
688	     *
689	     * @param registrationDate the business day to count owners for
690	     * @return the number of existing owners registered on that day
691	     */
692	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
693	        return this.clinicService.findAllOwners().stream()
694	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
695	            .count();
696	    }
697	
698	    /**
699	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
700	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
701	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
702	     * otherwise.
703	     *
704	     * @param ownerDto the owner response to flag
705	     */
706	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
707	        LocalDate today = toBusinessDay(LocalDate.now());
708	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
709	    }
710	
711	    /**
712	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
713	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
714	     * applies to the effective registration date whether it was supplied in the request or defaulted
715	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
716	     * feeds every value derived from it (such as the membership number's year segment and the daily
717	     * create-limit's per-day bucket).
718	     *
719	     * @param date the effective registration date, supplied or defaulted
720	     * @return the same date when it is a weekday, otherwise the next Monday
721	     */
722	    private LocalDate toBusinessDay(LocalDate date) {
723	        LocalDate adjusted = date;
724	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
725	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
726	            adjusted = adjusted.plusDays(1);
727	        }
728	        return adjusted;
729	    }
730	
731	    /**
732	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
733	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
734	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
735	     * separate telephone, email and household checks are all expressed through it. Because the
736	     * telephone is part of the key, two members of the same household (same {@code householdId})
737	     * with different telephones have different identity keys and are both allowed; only a whole-key
738	     * match is a duplicate. The owner being created already carries its normalized telephone,
739	     * email and (if any) household id, and existing owners store the same normalized forms, so the
740	     * keys are compared directly.
741	     *
742	     * @param owner the owner being created, with its telephone, email and household id already set
743	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
744	     *                                         yielding a 409 Conflict response
745	     */
746	    private void rejectDuplicateIdentity(Owner owner) {
747	        String identityKey = owner.getIdentityKey();
748	        boolean inUse = this.clinicService.findAllOwners().stream()
749	            .map(Owner::getIdentityKey)
750	            .anyMatch(identityKey::equals);
751	        if (inUse) {
752	            throw new DuplicateOwnerIdentityException(identityKey);
753	        }
754	    }
755	
756	    /**
757	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
758	     * that is not a hard duplicate (its identity key is unique, so it has already passed
759	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
760	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
761	     * while carrying a different telephone. When such a match exists the owner is created with
762	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
763	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
764	     * {@code false} and {@code possibleDuplicateOf} is left unset.
765	     *
766	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
767	     * declared household member is not a suspected duplicate. (Without that declaration a same-household
768	     * owner is rejected outright by {@link #rejectHouseholdDuplicate}, so no suspected-duplicate match
769	     * survives for a created owner either.)
770	     *
771	     * @param owner           the owner being created, with its household id and telephone already set
772	     * @param sharesHousehold whether the owner declared itself a member of an existing household
773	     */
774	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
775	        owner.setPossibleDuplicate(false);
776	        if (sharesHousehold) {
777	            return;
778	        }
779	        String householdId = owner.getHouseholdId();
780	        if (householdId == null || householdId.isBlank()) {
781	            return;
782	        }
783	        String telephone = owner.getTelephone();
784	        Owner match = this.clinicService.findAllOwners().stream()
785	            .filter(existing -> householdId.equals(existing.getHouseholdId())
786	                && !Objects.equals(telephone, existing.getTelephone()))
787	            .min(Comparator.comparingInt(Owner::getId))
788	            .orElse(null);
789	        if (match != null) {
790	            owner.setPossibleDuplicate(true);
791	            owner.setPossibleDuplicateOf(match.getId());
792	        }
793	    }
794	
795	    /**
796	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
797	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
798	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
799	     * shares both automatically shares the same household id, so the household is keyed on
800	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
801	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
802	     * still land in the same household.
803	     *
804	     * @param lastName the owner's last name
805	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
806	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
807	     *         to no postcode-keyed household
808	     */
809	    private String computeHouseholdId(String lastName, String postcode) {
810	        if (postcode == null) {
811	            return null;
812	        }
813	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
814	    }
815	
816	    /**
817	     * Rejects creation of an owner that would join an existing household it has not declared membership
818	     * of. The household is keyed on the computed {@code householdId} (derived from the last name and
819	     * postcode), so any existing owner carrying the same {@code householdId} is a member of the same
820	     * household. A second owner in that household is a household duplicate and is rejected with a
821	     * {@code 409 Conflict} unless the request opts in via {@code sharesHousehold}, in which case this
822	     * check is bypassed and the owner is created as a declared household member. An owner with no
823	     * {@code householdId} (no postcode) belongs to no household and is never rejected here.
824	     *
825	     * @param owner the owner being created, with its household id already computed
826	     * @throws DuplicateHouseholdException if an existing owner already belongs to the same
827	     *                                     household, yielding a 409 Conflict response
828	     */
829	    private void rejectHouseholdDuplicate(Owner owner) {
830	        String householdId = owner.getHouseholdId();
831	        if (householdId == null || householdId.isBlank()) {
832	            return;
833	        }
834	        boolean inUse = this.clinicService.findAllOwners().stream()
835	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
836	        if (inUse) {
837	            throw new DuplicateHouseholdException(householdId);
838	        }
839	    }
840	
841	    /**
842	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
843	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
844	     * the result is lower-cased.
845	     *
846	     * @param value the value to normalize, possibly {@code null}
847	     * @return the normalized value, or an empty string if {@code value} is {@code null}
848	     */
849	    private String normalizeForComparison(String value) {
850	        if (value == null) {
851	            return "";
852	        }
853	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
854	    }
855	
856	    /**
857	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
858	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
859	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
860	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
861	     * This normalized value is what gets stored and returned.
862	     *
863	     * @param address the raw address value submitted by the client, possibly {@code null}
864	     * @return the normalized address, or an empty string if {@code address} is {@code null}
865	     */
866	    private String normalizeAddress(String address) {
867	        if (address == null) {
868	            return "";
869	        }
870	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
871	        if (collapsed.isEmpty()) {
872	            return collapsed;
873	        }
874	        String[] tokens = collapsed.split(" ");
875	        StringBuilder normalized = new StringBuilder(collapsed.length());
876	        for (int i = 0; i < tokens.length; i++) {
877	            if (i > 0) {
878	                normalized.append(' ');
879	            }
880	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
881	        }
882	        return normalized.toString();
883	    }
884	}
